/**
 * Regenerates the map of topics that have a real video still.
 *
 *   npm run stills:topic
 *
 * Stills live in public/img/topics/<docId>.jpg and are extracted from the
 * topic video with ffmpeg. The manifest is committed so the app never probes
 * the filesystem at runtime.
 */
import { readdirSync, writeFileSync } from "node:fs";

const ids = readdirSync("public/img/topics")
  .filter((f) => f.endsWith(".jpg"))
  .map((f) => f.replace(/\.jpg$/, ""))
  .sort();

writeFileSync(
  "lib/topic-stills.ts",
  `/**
 * Generated by scripts/topic-stills.ts — do not edit by hand.
 *
 * Topics with a still extracted from their video, at public/img/topics/<id>.jpg.
 */
export const TOPIC_STILL_IDS = new Set<string>([
${ids.map((id) => `  ${JSON.stringify(id)},`).join("\n")}
]);

/** Still URL for a topic document, or undefined when there is none. */
export function topicStillUrl(docId: string): string | undefined {
  return TOPIC_STILL_IDS.has(docId) ? \`/img/topics/\${docId}.jpg\` : undefined;
}
`,
);
console.log(`wrote lib/topic-stills.ts with ${ids.length} stills`);
